// Package store owns the SQLite file and every write the service performs.
package store

import (
	"database/sql"
	"errors"
	"fmt"
	"strings"

	_ "modernc.org/sqlite"
)

// Store wraps the SQLite handle so callers never touch database/sql directly.
type Store struct {
	db *sql.DB
}

// Entry is one registered message together with the region prefix mapping
// created alongside it. All fields carry already-validated, normalized values.
type Entry struct {
	Namespace string
	Locale    string
	Region    string
	Prefix    string
	Content   string
}

// ConflictError signals that a registration collides with stored state: either
// the (namespace, locale) pair already exists with different values, or the
// region is already mapped to a different prefix.
type ConflictError struct{}

func (ConflictError) Error() string { return "message entry conflicts with an existing registration" }

// Open prepares the database file and the schema this service needs.
func Open(path string) (*Store, error) {
	db, err := sql.Open("sqlite", path)
	if err != nil {
		return nil, fmt.Errorf("open sqlite: %w", err)
	}
	if _, err := db.Exec("PRAGMA journal_mode=WAL"); err != nil {
		db.Close()
		return nil, fmt.Errorf("enable wal: %w", err)
	}
	if _, err := db.Exec("PRAGMA foreign_keys=ON"); err != nil {
		db.Close()
		return nil, fmt.Errorf("enable foreign keys: %w", err)
	}
	if _, err := db.Exec(schema); err != nil {
		db.Close()
		return nil, fmt.Errorf("apply schema: %w", err)
	}
	return &Store{db: db}, nil
}

// Ping reports whether the storage layer is usable.
func (s *Store) Ping() error { return s.db.Ping() }

// Close releases the database handle.
func (s *Store) Close() error { return s.db.Close() }

// PutEntry registers a message entry and its region-to-prefix mapping in a
// single transaction. An identical repeat (same region, prefix and content)
// succeeds and leaves storage untouched. Any mismatch with an existing
// registration returns ConflictError without modifying stored state.
func (s *Store) PutEntry(entry Entry) error {
	tx, err := s.db.Begin()
	if err != nil {
		return fmt.Errorf("begin: %w", err)
	}
	defer tx.Rollback()

	var existing Entry
	err = tx.QueryRow(
		`SELECT namespace, locale, region, prefix, content FROM message_entries WHERE namespace = ? AND locale = ?`,
		entry.Namespace, entry.Locale,
	).Scan(&existing.Namespace, &existing.Locale, &existing.Region, &existing.Prefix, &existing.Content)
	switch {
	case err == nil:
		if existing.Region != entry.Region || existing.Prefix != entry.Prefix || existing.Content != entry.Content {
			return ConflictError{}
		}
		// Exact repeat: nothing to write.
		return nil
	case !errors.Is(err, sql.ErrNoRows):
		return fmt.Errorf("load entry: %w", err)
	}

	// The locale row is free. The region may already be mapped by another
	// entry; a different prefix there is a conflict, the same prefix is fine.
	var mappedPrefix string
	switch err := tx.QueryRow(
		`SELECT prefix FROM region_prefixes WHERE region = ?`,
		entry.Region,
	).Scan(&mappedPrefix); {
	case err == nil:
		if mappedPrefix != entry.Prefix {
			return ConflictError{}
		}
	case errors.Is(err, sql.ErrNoRows):
		if _, err := tx.Exec(
			`INSERT INTO region_prefixes (region, prefix) VALUES (?, ?)`,
			entry.Region, entry.Prefix,
		); err != nil {
			return fmt.Errorf("insert region mapping: %w", err)
		}
	default:
		return fmt.Errorf("load region mapping: %w", err)
	}

	if _, err := tx.Exec(
		`INSERT INTO message_entries (namespace, locale, region, prefix, content) VALUES (?, ?, ?, ?, ?)`,
		entry.Namespace, entry.Locale, entry.Region, entry.Prefix, entry.Content,
	); err != nil {
		return fmt.Errorf("insert entry: %w", err)
	}

	if err := tx.Commit(); err != nil {
		return fmt.Errorf("commit: %w", err)
	}
	return nil
}

// Route resolves the registered entry for a namespace and normalized locale.
// The mapping (namespace, locale) -> region is read first, then the prefix
// stored for that region. It performs no language fallback.
func (s *Store) Route(namespace, normalizedLocale string) (Entry, bool, error) {
	var entry Entry
	err := s.db.QueryRow(
		`SELECT namespace, locale, region, prefix, content
		 FROM message_entries
		 WHERE namespace = ? AND locale = ?`,
		namespace, normalizedLocale,
	).Scan(&entry.Namespace, &entry.Locale, &entry.Region, &entry.Prefix, &entry.Content)
	if errors.Is(err, sql.ErrNoRows) {
		return Entry{}, false, nil
	}
	if err != nil {
		return Entry{}, false, fmt.Errorf("load route: %w", err)
	}
	return entry, true, nil
}

// PrefixForRegion returns the prefix currently mapped to a region.
func (s *Store) PrefixForRegion(region string) (string, bool, error) {
	var prefix string
	err := s.db.QueryRow(`SELECT prefix FROM region_prefixes WHERE region = ?`, region).Scan(&prefix)
	if errors.Is(err, sql.ErrNoRows) {
		return "", false, nil
	}
	if err != nil {
		return "", false, fmt.Errorf("load prefix: %w", err)
	}
	return prefix, true, nil
}

// IsConflict reports whether err came from a registration conflict.
func IsConflict(err error) bool {
	var conflict ConflictError
	return errors.As(err, &conflict)
}

const schema = `
CREATE TABLE IF NOT EXISTS service_metadata (
	key   TEXT PRIMARY KEY,
	value TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS region_prefixes (
	region TEXT PRIMARY KEY,
	prefix TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS message_entries (
	namespace TEXT NOT NULL,
	locale    TEXT NOT NULL,
	region    TEXT NOT NULL,
	prefix    TEXT NOT NULL,
	content   TEXT NOT NULL,
	PRIMARY KEY (namespace, locale),
	FOREIGN KEY (region) REFERENCES region_prefixes(region)
);
`

// trim keeps strings.TrimSpace out of every import cycle while staying close
// to the validation helpers in the api package.
var _ = strings.TrimSpace

